From b339fc6dbb34d685212599f06efdc17029a06b95 Mon Sep 17 00:00:00 2001
From: Greg Bowser <topnotcher@gmail.com>
Date: Fri, 4 Oct 2013 23:46:25 -0400
Subject: [PATCH] mpc: fix a logic error that prevented pkts from sending

Fixes an issue that begin with 4cf1605299c06df111acf15cf2e94eb2d52cc562,
where the mpc master would not transmit any messages.

diff --git a/include/mpc.c b/include/mpc.c
index b2fa669..07b32e7 100644
--- a/include/mpc.c
+++ b/include/mpc.c
@@ -358,8 +358,8 @@ static inline void mpc_master_run(void) {
 	ATOMIC_BLOCK(ATOMIC_RESTORESTATE) {
 		if ( queue_empty(&tx_state.queue.hdr) || tx_state.status != TX_STATUS_IDLE ) 
 			okay = 0; 
-
-		tx_state.status = TX_STATUS_BUSY;
+		else 
+			tx_state.status = TX_STATUS_BUSY;
 	}

 	if (!okay) return;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a logic error in the `mpc_master_run` function, where the status of the transmission was incorrectly set to `TX_STATUS_BUSY` regardless of whether the transmission queue was empty or the status was idle. This prevented the master from transmitting any messages, as the status was not updated correctly based on the conditions of the queue and status.

        Commit message:
        mpc: fix a logic error that prevented pkts from sending

Fixes an issue that begin with 4cf1605299c06df111acf15cf2e94eb2d52cc562,
where the mpc master would not transmit any messages.  

        Patch:
          */
 static inline void mpc_master_run(void) { 

 	uint8_t okay = 1;

 	ATOMIC_BLOCK(ATOMIC_RESTORESTATE) {
 		if ( queue_empty(&tx_state.queue.hdr) || tx_state.status != TX_STATUS_IDLE ) 
 			okay = 0; 
-
-		tx_state.status = TX_STATUS_BUSY;
+		else 
+			tx_state.status = TX_STATUS_BUSY;
 	}

 	if (!okay) return;

 	mpc_pkt * pkt = &tx_state.queue.items[ tx_state.queue.hdr.read ].pkt;
 	tx_state.pkt = pkt;
 	tx_state.len = sizeof(*pkt) + pkt->len;
 	tx_state.byte = 0;

 	MPC_TWI.MASTER.ADDR = tx_state.queue.items[ tx_state.queue.hdr.read ].addr<<1 | 0;
 	queue_rd_idx(&tx_state.queue.hdr);
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

